function dir$qldctcccdCheckbox(p){
	// 1) Đảm bảo phần tử .check là relative (để ::before định vị theo nó)
	document.querySelectorAll('.checkbox .checkbox-material .check').forEach(function(el){
	  el.style.position = 'relative';
	  el.style.width = '18px';
	  el.style.height = '18px';
	  el.style.border = '2px solid #0d6efd';
	  el.style.borderRadius = '50%';
	  el.style.boxSizing = 'border-box';
	  el.style.background = '#fff';
	});

	// 2) Tiêm CSS cho pseudo-element ::before (vẽ dấu tick kiểu material)
	const css = `
	.checkbox .checkbox-material .check::before {
	  content: "";
	  position: absolute;
	  top: 3px;
	  left: 6px;
	  width: 6px;
	  height: 10px;
	  transform: rotate(45deg);
	  display: block;
	  border-right: 3px solid #0d6efd;
	  border-bottom: 3px solid #0d6efd;
	  opacity: 0;
	  transition: opacity .2s ease;
	}

	/* Ví dụ: khi được "checked" thì hiện tick (tùy class hoặc state bạn dùng) */
	.checkbox.is-checked .checkbox-material .check::before {
	  opacity: 1;
	}

	/* Nếu bạn muốn hiệu ứng bật/tắt */
	@keyframes checkbox-on { from { opacity: 0 } to { opacity: 1 } }
	@keyframes checkbox-off { from { opacity: 1 } to { opacity: 0 } }
	`;

	const styleTag = document.createElement('style');
	styleTag.type = 'text/css';
	styleTag.appendChild(document.createTextNode(css));
	document.head.appendChild(styleTag);

	// (Tuỳ chọn) Toggle class .is-checked theo input radio/checkbox của bạn:
	document.querySelectorAll('.checkbox input[type="radio"], .checkbox input[type="checkbox"]').forEach(function(input){
	  const root = input.closest('.checkbox');
	  if (!root) return;

	  // set trạng thái ban đầu
	  root.classList.toggle('is-checked', input.checked);

	  // lắng nghe thay đổi
	  input.addEventListener('change', function(){
		// nếu là radio: bỏ .is-checked ở group cùng name
		if (input.type === 'radio' && input.name) {
		  document.querySelectorAll('.checkbox input[type="radio"][name="'+input.name+'"]').forEach(function(r){
			const rr = r.closest('.checkbox');
			if (rr) rr.classList.toggle('is-checked', r.checked);
		  });
		} else {
		  root.classList.toggle('is-checked', input.checked);
		}
	  });
	});
}

dir$qldctcccd.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
	var element = p.valForm('thuongtru_yn');
	var element2 = p.valForm('tamtru_yn');

  switch (cF){
	case 'so_cccd':
		if(p.options.action == "NEW")
		{
			dir$qldctcccdCreateCode(p);
		}
		break;
	case 'ngay_cap':
		if(p.options.action == "NEW")
		{
			dir$qldctcccdCreateCode(p);
		}
		break;
	case 'thuongtru_yn':
		// Xử lý khi điều kiện thỏa mãn
		if (element === 1) {
			p.valForm('tamtru_yn', 0, '')
		} else {
			p.valForm('thuongtru_yn', 1, '')
		}

		console.log(p.valForm('thuongtru_yn'));
		console.log(p.valForm('tamtru_yn'));
      break;
	case 'tamtru_yn':
		if (element2 === 1) {
			p.valForm('thuongtru_yn', 0, '')
		} else {
			p.valForm('tamtru_yn', 1, '')
		}

		console.log(p.valForm('thuongtru_yn'));
		console.log(p.valForm('tamtru_yn'));
	break;
	default:
      break;
	}
}

function dir$qldctcccdCreateCode(p) {
	var ngayCap = p.valForm('ngay_cap'), soCCCD = p.valForm('so_cccd');

	const date = new Date(ngayCap);
	const yyyy = date.getFullYear();
	const mm = String(date.getMonth() + 1).padStart(2, '0'); // Tháng bắt đầu từ 0
	const dd = String(date.getDate()).padStart(2, '0');
	const formattedDate = `${yyyy}${mm}${dd}`;
	return p.valForm('ma_dancu', `MDC${formattedDate}${soCCCD}`, true);

}






